// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.doAnswer;

import org.eclipse.kura.KuraException;
import org.junit.Test;

public class EnforcementSweepTest extends AbstractEnforcementTest {

    private RuntimeException unregisterFailure;

    @Test
    public void startEnforcingReturnsAfterTheStartupSweep() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);

        whenEnforcementStarts();

        thenSchedulerRanTasks(1);
        thenContainerWasDeleted(CONTAINER_ID);
    }

    @Test
    public void unregisterWaitsForTheScheduler() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainerRegistering(OTHER_CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcement();

        whenContainerIsRemoved(OTHER_CONTAINER_ID);

        thenNoContainerWasDeleted();
    }

    @Test
    public void unregisterSweepRunsOnTheScheduler() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainerRegistering(OTHER_CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcement();
        givenContainerRemoved(OTHER_CONTAINER_ID);

        whenSchedulerRunsPendingTasks();

        thenContainerWasDeleted(CONTAINER_ID);
    }

    @Test
    public void unregisterDoesNotSurfaceSweepFailures() {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainerRegistering(OTHER_CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcement();
        givenContainerListingFails();

        whenContainerIsRemoved(OTHER_CONTAINER_ID);

        thenUnregisterDidNotFail();
    }

    @Test
    public void requestsWhileASweepIsPendingShareOneSweep() {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainerRegistering(OTHER_CONTAINER_ID, OTHER_IMAGE_DIGEST);
        givenRunningContainerRegistering(THIRD_CONTAINER_ID, OTHER_IMAGE_DIGEST);
        givenStartedEnforcement();
        givenContainerRemoved(OTHER_CONTAINER_ID);
        givenContainerRemoved(THIRD_CONTAINER_ID);

        whenSchedulerRunsPendingTasks();

        thenContainersWereListed(2);
    }

    @Test
    public void requestDuringASweepTriggersAnotherSweep() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainerRegistering(OTHER_CONTAINER_ID, OTHER_IMAGE_DIGEST);
        givenDeletingTheContainerUnregistersDigestOf(OTHER_CONTAINER_ID);

        whenEnforcementStarts();

        thenContainersWereListed(2);
    }

    @Test
    public void sweepDroppedAtCloseDoesNotBlockTheNextStart() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainerRegistering(OTHER_CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcement();
        givenContainerRemoved(OTHER_CONTAINER_ID);
        givenClosedEnforcement();

        whenEnforcementStarts();

        thenContainerWasDeleted(CONTAINER_ID);
    }

    private void givenRunningContainerRegistering(String containerId, String digest) {
        givenRunningContainer(containerId, digest);
        givenDigestRegisteredBy(containerId, digest);
    }

    private void givenContainerRemoved(String containerId) {
        stopRunning(containerId);
        givenDigestUnregisteredBy(containerId);
    }

    private void givenDeletingTheContainerUnregistersDigestOf(String containerId) throws KuraException {
        doAnswer(invocation -> {
            this.enforcement.unregister(containerId);
            return null;
        }).when(this.target).forceDeleteContainer(CONTAINER_ID);
    }

    private void whenContainerIsRemoved(String containerId) {
        stopRunning(containerId);
        try {
            this.enforcement.unregister(containerId);
        } catch (RuntimeException e) {
            this.unregisterFailure = e;
        }
    }

    private void thenSchedulerRanTasks(int expectedTasks) {
        assertEquals(expectedTasks, this.scheduler.ranTaskCount());
    }

    private void thenUnregisterDidNotFail() {
        assertNull(this.unregisterFailure);
    }
}
